import { MENU_IMAGE_BLUR } from "@/data/menu-image-blur.generated";

/** Widths generated by `scripts/optimize-images.mjs`, ascending. */
export const MENU_IMAGE_WIDTHS = [400, 640, 960] as const;

export const FALLBACK_MENU_IMAGE = "/images/burger.jpg";

/**
 * Stable key for a menu image: the lower-cased file name without extension.
 * Menu rows in the database may still point at the legacy folders
 * (`Orignal_Images`, `Webp_Orignal_images`, `Pizza_Images`), so the key is
 * folder- and extension-agnostic.
 */
export function getMenuImageKey(path?: string | null): string | null {
  if (!path || !path.startsWith("/images/")) return null;
  const key = path.slice(path.lastIndexOf("/") + 1).replace(/\.[a-z0-9]+$/i, "").toLowerCase();
  return key in MENU_IMAGE_BLUR ? key : null;
}

/** URL of the pre-built variant closest to (and not smaller than) `width`. */
export function getMenuImageUrl(key: string, width: number): string {
  const variant = MENU_IMAGE_WIDTHS.find((w) => w >= width) ?? MENU_IMAGE_WIDTHS[MENU_IMAGE_WIDTHS.length - 1];
  return `/images/menu/${key}-${variant}.webp`;
}

export function getMenuImageBlur(path?: string | null): string | undefined {
  const key = getMenuImageKey(path);
  return key ? MENU_IMAGE_BLUR[key] : undefined;
}
